import{_ as i,o as a,c as t,an as r}from"./chunks/framework.CWR6eSMD.js";const g=JSON.parse('{"title":"Release notes","description":"","frontmatter":{},"headers":[],"relativePath":"release-notes.md","filePath":"release-notes.md","lastUpdated":null}'),s={name:"release-notes.md"};function l(o,e,p,n,d,m){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="Release-notes" tabindex="-1">Release notes <a class="header-anchor" href="#Release-notes" aria-label="Permalink to &quot;Release notes {#Release-notes}&quot;">​</a></h1><p>Every release of this package is published as a GitHub release. The most recent are reproduced below, as they were written there.</p><h2 id="v0.1.0" tabindex="-1">v0.1.0 <a class="header-anchor" href="#v0.1.0" aria-label="Permalink to &quot;v0.1.0 {#v0.1.0}&quot;">​</a></h2><p>Released 2026-07-31. <a href="https://github.com/EpiAware/ReparameterisedDistributions.jl/releases/tag/v0.1.0" target="_blank" rel="noreferrer">Read it on GitHub</a>.</p><p>First release. Adds core functionality as well as package infrastructure.</p><p><strong>Closed issues:</strong></p><ul><li><p>Add package infrastructure (#1)</p></li><li><p>Update to hosting at EpiAware (#3)</p></li><li><p>Update to use EpiAware skeleton (#4)</p></li><li><p>Add mean and sd parameterisation for common univariate distributions (#5)</p></li><li><p>Gamma: mean and sd (#6)</p></li><li><p>Lognormal: mean and sd (#7)</p></li><li><p>Negative binomial parameterisations (#8)</p></li><li><p>Neg bin: mean and dispersion (#9)</p></li><li><p>Neg bin: mean and clustering factor (#10)</p></li><li><p>Neg bin: Log input (#11)</p></li><li><p>Neg bin: GLM optimised likelihood (#12)</p></li><li><p>Poisson (#13)</p></li><li><p>Poisson: Log input (#14)</p></li><li><p>Poisson: GLM optimised (#15)</p></li><li><p>Package rename (#16)</p></li><li><p>Explore DistributionFactories to see what the overlap is (#17)</p></li><li><p>Modernise onto current EpiAwarePackageTools infra (ad=true) + KIT AD harness (#18)</p></li><li><p>Core: AbstractReparameterisedDistribution + reparameterise() constructor (moment-param wrapper) (#19)</p></li><li><p>Closed-form mean+sd reparameterisations: LogNormal + Gamma (priority) + NegBinomial mean+overdispersion (#20)</p></li><li><p>Port the moment-parameterisation wrapper from CensoredDistributions (CD#725) (#21)</p></li><li><p>Triage the legacy #7–#17 per-family backlog against the generic wrapper (#22)</p></li><li><p>Manual setup for ReparameterisedDistributions (Codecov, Pages, branch protection, registration) (#24)</p></li><li><p>Scaffold text left in docs. (#36)</p></li><li><p>Remove refs to other packages/epi people won&#39;t know (#37)</p></li><li><p>Add a approach to get the original params of the distribution i.e the internal params (#38)</p></li><li><p>Review AD support and make sure all working (#40)</p></li><li><p>Package logo missing (#42)</p></li><li><p>_to_native (#43)</p></li><li><p>Custom show method (#44)</p></li><li><p>Type stability of reparameterised named tuple (#45)</p></li><li><p>Align author credits across Project.toml, CITATION.cff and docs (needs @seabbs ruling) (#48)</p></li><li><p>Family-agnostic mean rescaling verb (#52)</p></li><li><p>Register the reciprocal dispersion parameterisation for the negative binomial (#53)</p></li><li><p>Rate parameterisations for the exponential and gamma families (#54)</p></li><li><p>Register a skew-normal parameterisation keyed on a tail probability (#55)</p></li></ul><p>Every release, including any older than those above, is listed on the <a href="https://github.com/EpiAware/ReparameterisedDistributions.jl/releases" target="_blank" rel="noreferrer">releases page</a>.</p>',8)])])}const u=i(s,[["render",l]]);export{g as __pageData,u as default};
